const API_BASE = (process.env.REACT_APP_API_URL || "").replace(/\/$/, "");

if (process.env.NODE_ENV === "development" && typeof window !== "undefined" && !API_BASE) {
  console.warn(
    "[BrewMart] REACT_APP_API_URL is empty. Set it in frontend/.env to your API (e.g. http://localhost:4000) and restart npm start."
  );
}

export function getApiBase() {
  return API_BASE;
}

/**
 * @param {string} path
 * @param {RequestInit & { json?: unknown }} [opts]
 */
export async function apiFetch(path, opts = {}) {
  const url = `${API_BASE}${path.startsWith("/") ? path : `/${path}`}`;
  const headers = new Headers(opts.headers || {});
  if (opts.json !== undefined) {
    headers.set("Content-Type", "application/json");
  }
  const init = {
    ...opts,
    headers,
    credentials: opts.credentials ?? "include",
    body: opts.json !== undefined ? JSON.stringify(opts.json) : opts.body
  };
  delete init.json;
  const res = await fetch(url, init);
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = { raw: text };
  }
  if (!res.ok) {
    const msg =
      data && data.error && data.error.message
        ? data.error.message
        : `Request failed (${res.status})`;
    const err = new Error(msg);
    err.status = res.status;
    err.data = data;
    throw err;
  }
  return data;
}
